def solve(meetings):
    # Greedy activity selection: sort by end time
    if not meetings:
        return 0
    # sort by end, then start (optional)
    meetings_sorted = sorted(meetings, key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for start, end in meetings_sorted:
        if start >= current_end:
            count += 1
            current_end = end
    return count

