def solve(a, b):
    n, m = len(a), len(b)
    # DP with two rows
    prev = list(range(m+1))
    for i in range(1, n+1):
        cur = [i] + [0]*m
        for j in range(1, m+1):
            if a[i-1] == b[j-1]:
                cost = 0
            else:
                cost = 1
            cur[j] = min(prev[j] + 1,          # deletion
