{"task_id": "T21", "code": "def solve(weights, values, capacity):
    # 0/1 knapsack with 1D DP
    n = len(weights)
    if capacity <= 0 or n == 0:
        return 0
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # iterate backwards to avoid reuse
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]
