def solve(coins, amount):
    # DP: dp[i] = min number of coins to make i, init large
    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] != max_val else -1

def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes with a bytearray for efficiency.
    """
    if n <= 2:
        return 0
    limit = n
    sieve = bytearray(b'\x01') * limit
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit - 1)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit:step] = b'\x00' * ((limit - start - 1) // step + 1)
    return sum(sieve)

