def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Digits 0-9 then a-z are used. Negative numbers get a leading '-'.
    """
    if b < 2 or b > 36:
        raise ValueError("Base out of range")
    # Zero case
    if n == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    negative = n < 0
    n_abs = -n if negative else n
    res_chars = []
    while n_abs > 0:
        n_abs, rem = divmod(n_abs, b)
        res_chars.append(digits[rem])
    if negative:
        res_chars.append('-')
    return ''.join(reversed(res_chars))

