def solve(s):
    """Validate IPv4 address string.
    Returns True if s is exactly four decimal numbers 0-255 separated by dots,
    with no leading zeros unless the component is '0'.
    """
    if not isinstance(s, str):
        return False
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        # each part must be non-empty and consist only of digits
        if not p.isdigit():
            return False
        # no leading zeros unless the part is exactly '0'
        if len(p) > 1 and p[0] == '0':
            return False
        # numeric range 0-255
        val = int(p)
        if val < 0 or val > 255:
            return False
    return True

