def solve(s: str) -> int:
    # Mapping of single Roman numerals to their integer values
    value = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
             'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        # If the current numeral is less than the next, it's a subtractive pair
        if i + 1 < n and value[s[i]] < value[s[i + 1]]:
            total += value[s[i + 1]] - value[s[i]]
            i += 2
        else:
            total += value[s[i]]
            i += 1
    return total

