def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in nums:
        # find insertion point (first >= x) because we need strictly increasing, so use bisect_left
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

